Here is a Python function that merges overlapping intervals by adding a new interval to the list. The intervals are returned as a list of [start, end] pairs, sorted by start.

```python
def merge_intervals(intervals):
    if len(intervals) == 0:
        return []
    elif len(intervals) == 1:
        return intervals
    else:
        intervals.sort(key=lambda x: x[0])  # sort intervals by start
        merged = [intervals[0]]  # store the first interval
        for i in range(1, len(intervals)):
            if intervals[i][0] <= merged[-1][1]:  # If the current interval overlaps with the last interval
                merged[-1][1] = max(intervals[i][1], merged[-1][1])  # Merge the intervals
            else:
                merged.append(intervals[i])  # Add the current interval to the merged list
        return merged
